import type {
  QueryFilter,
  QueryFilterCondition,
} from '@process.co/table-client';
import { z } from 'zod';

const identifier = z.string().trim().min(1).max(200);

export const listDatasetsInputSchema = z.object({}).strict();

export const inspectDatasetInputSchema = z
  .object({
    datasetId: identifier.describe('Logical Process dataset id'),
  })
  .strict();

const queryFilterConditionSchema: z.ZodType<QueryFilterCondition> = z
  .object({
    field: z.string().trim().min(1).max(300),
    operator: z.enum([
      'eq',
      'ne',
      'gt',
      'gte',
      'lt',
      'lte',
      'contains',
      'in',
      'empty',
      'notEmpty',
    ]),
    value: z.unknown().optional(),
  })
  .strict();

export const queryFilterSchema: z.ZodType<QueryFilter> = z.lazy(() =>
  z
    .object({
      conjunction: z.enum(['and', 'or']).optional(),
      conditions: z.array(queryFilterConditionSchema).max(20).optional(),
      groups: z.array(queryFilterSchema).max(4).optional(),
    })
    .strict(),
);

export const queryRowsInputSchema = z
  .object({
    datasetId: identifier.describe('Logical Process dataset id'),
    filter: queryFilterSchema.optional(),
    sort: z
      .array(
        z
          .object({
            field: z.string().trim().min(1).max(300),
            direction: z.union([z.literal(1), z.literal(-1)]),
            nulls: z.enum(['first', 'last']),
          })
          .strict(),
      )
      .max(8)
      .optional(),
    cursor: z.string().trim().min(1).max(2_000).optional(),
    limit: z.number().int().positive().max(200).optional(),
  })
  .strict()
  .superRefine((input, ctx) => {
    if (input.filter && filterDepth(input.filter) > 4) {
      ctx.addIssue({
        code: 'custom',
        path: ['filter'],
        message: 'filter nesting exceeds four levels',
      });
    }
  });

export const getRowInputSchema = z
  .object({
    datasetId: identifier.describe('Logical Process dataset id'),
    rowId: identifier.describe('Logical row id'),
  })
  .strict();

export const insertRowInputSchema = z
  .object({
    datasetId: identifier.describe('Logical Process dataset id'),
    groupId: identifier.optional(),
    parentRowId: identifier.optional(),
    value: z.string().min(1).max(20_000),
    columns: z
      .record(z.string().trim().min(1).max(300), z.unknown())
      .optional(),
  })
  .strict();

export const updateRowInputSchema = z
  .object({
    datasetId: identifier.describe('Logical Process dataset id'),
    rowId: identifier.describe('Logical row id'),
    value: z.string().max(20_000).optional(),
    columns: z
      .record(z.string().trim().min(1).max(300), z.unknown())
      .optional(),
    groupId: identifier.optional(),
    rank: z.string().trim().min(1).max(500).optional(),
  })
  .strict()
  .refine(
    (input) =>
      input.value !== undefined ||
      input.columns !== undefined ||
      input.groupId !== undefined ||
      input.rank !== undefined,
    { message: 'row patch must not be empty' },
  );

export const deleteRowInputSchema = getRowInputSchema;

function filterDepth(filter: QueryFilter): number {
  if (!filter.groups?.length) return 1;
  return 1 + Math.max(...filter.groups.map(filterDepth));
}
