import { TableServiceError } from '@process.co/table-client';
import { ZodError } from 'zod';

export class ProcessTableToolError extends Error {
  readonly code: string;
  readonly statusCode: number;
  readonly requestId: string;

  constructor(input: { code: string; statusCode: number; requestId: string }) {
    super(`Process Table tool failed (${input.code})`);
    this.name = 'ProcessTableToolError';
    this.code = input.code;
    this.statusCode = input.statusCode;
    this.requestId = input.requestId;
  }

  toJSON(): {
    code: string;
    statusCode: number;
    requestId: string;
  } {
    return {
      code: this.code,
      statusCode: this.statusCode,
      requestId: this.requestId,
    };
  }
}

export function toProcessTableToolError(error: unknown): ProcessTableToolError {
  if (error instanceof ProcessTableToolError) return error;
  if (error instanceof ZodError) {
    return new ProcessTableToolError({
      code: 'VALIDATION_ERROR',
      statusCode: 400,
      requestId: '',
    });
  }
  if (error instanceof TableServiceError) {
    return new ProcessTableToolError({
      code: error.code,
      statusCode: error.statusCode,
      requestId: error.requestId,
    });
  }
  // Packed consumers may load a second copy of table-client, so preserve the
  // structural boundary without combining it with instanceof narrowing.
  if (isTableServiceErrorLike(error)) {
    return new ProcessTableToolError({
      code: error.code,
      statusCode: error.statusCode,
      requestId: error.requestId,
    });
  }
  return new ProcessTableToolError({
    code: 'INTERNAL_ERROR',
    statusCode: 500,
    requestId: '',
  });
}

function isTableServiceErrorLike(error: unknown): error is {
  code: string;
  statusCode: number;
  requestId: string;
} {
  return (
    typeof error === 'object' &&
    error !== null &&
    'code' in error &&
    typeof error.code === 'string' &&
    'statusCode' in error &&
    typeof error.statusCode === 'number' &&
    'requestId' in error &&
    typeof error.requestId === 'string'
  );
}
