import {
  TableClient,
  type CanonicalRow,
  type DatasetDiscoveryResponse,
  type DatasetResponse,
  type DeleteRowResponse,
  type InsertRowRequest,
  type LayoutResponse,
  type PatchRowRequest,
  type QueryRowsRequest,
  type QueryRowsResponse,
  type TableRowMutationContext,
} from '@process.co/table-client';
import { tool, zodSchema, type ToolSet } from 'ai';
import type { z } from 'zod';
import {
  deleteRowInputSchema,
  getRowInputSchema,
  inspectDatasetInputSchema,
  insertRowInputSchema,
  listDatasetsInputSchema,
  queryRowsInputSchema,
  updateRowInputSchema,
} from './schemas';
import { ProcessTableToolError, toProcessTableToolError } from './errors';

export const PROCESS_TABLE_TOOL_LIMITS = {
  defaultMaxQueryRows: 50,
  hardMaxQueryRows: 200,
  defaultMaxInputBytes: 32 * 1024,
  hardMaxInputBytes: 128 * 1024,
  defaultMaxResultBytes: 256 * 1024,
  hardMaxResultBytes: 1024 * 1024,
} as const;

export const PROCESS_TABLE_READ_TOOL_NAMES = [
  'listProcessDatasets',
  'inspectProcessDataset',
  'queryProcessRows',
  'getProcessRow',
] as const;

export const PROCESS_TABLE_MUTATION_TOOL_NAMES = [
  'insertProcessRow',
  'updateProcessRow',
  'deleteProcessRow',
] as const;

export type ProcessTableToolClient = Pick<
  TableClient,
  | 'listDatasets'
  | 'getDataset'
  | 'getLayout'
  | 'queryRows'
  | 'getRow'
  | 'insertRow'
  | 'patchRow'
  | 'deleteRow'
>;

export type ProcessTableToolsOptions = {
  client: ProcessTableToolClient;
  limits?: {
    maxQueryRows?: number;
    maxInputBytes?: number;
    maxResultBytes?: number;
  };
  mutations?: {
    enabled: true;
  };
};

type ToolLimits = {
  maxQueryRows: number;
  maxInputBytes: number;
  maxResultBytes: number;
};

export function createProcessTableTools(
  options: ProcessTableToolsOptions,
): ToolSet {
  if (!options?.client) {
    throw new TypeError('client is required');
  }
  const limits = resolveLimits(options.limits);
  const reads: ToolSet = {
    listProcessDatasets: tool({
      description:
        'List logical Process datasets accessible to the current server-side principal.',
      inputSchema: listDatasetsInputSchema,
      execute: (input) =>
        executeBounded(listDatasetsInputSchema, input, limits, async () =>
          projectDiscovery(await options.client.listDatasets()),
        ),
    }),
    inspectProcessDataset: tool({
      description:
        'Inspect safe capabilities, schema, groups, and views for one logical Process dataset.',
      inputSchema: inspectDatasetInputSchema,
      execute: (input) =>
        executeBounded(
          inspectDatasetInputSchema,
          input,
          limits,
          async (parsed) => {
            const [dataset, layout] = await Promise.all([
              options.client.getDataset(parsed.datasetId),
              options.client.getLayout(parsed.datasetId),
            ]);
            return projectInspection(dataset, layout);
          },
        ),
    }),
    queryProcessRows: tool({
      description:
        'Run one bounded filter/sort query against a logical Process dataset.',
      inputSchema: zodSchema(queryRowsInputSchema, { useReferences: true }),
      execute: (input) =>
        executeBounded(queryRowsInputSchema, input, limits, async (parsed) => {
          const { datasetId, ...query } = parsed;
          const requestedLimit = query.limit ?? limits.maxQueryRows;
          const response = await options.client.queryRows(datasetId, {
            ...query,
            limit: Math.min(requestedLimit, limits.maxQueryRows),
          } as QueryRowsRequest);
          return projectQuery(response, limits.maxQueryRows);
        }),
    }),
    getProcessRow: tool({
      description:
        'Read one logical Process row and its bounded detail envelope.',
      inputSchema: getRowInputSchema,
      execute: (input) =>
        executeBounded(getRowInputSchema, input, limits, (parsed) =>
          options.client.getRow(parsed.datasetId, parsed.rowId),
        ),
    }),
  };

  if (!options.mutations?.enabled) return reads;

  return {
    ...reads,
    insertProcessRow: tool({
      description:
        'Insert one Process row. This mutates data and always requires user approval.',
      inputSchema: insertRowInputSchema,
      needsApproval: true,
      execute: (input, execution) =>
        executeMutation(insertRowInputSchema, input, limits, async (parsed) => {
          const context = agentMutationContext(execution.toolCallId);
          const { datasetId, ...body } = parsed;
          const row = await options.client.insertRow(
            datasetId,
            body as InsertRowRequest,
            context,
          );
          return mutationResult(context, row);
        }),
    }),
    updateProcessRow: tool({
      description:
        'Patch one Process row. This mutates data and always requires user approval.',
      inputSchema: updateRowInputSchema,
      needsApproval: true,
      execute: (input, execution) =>
        executeMutation(updateRowInputSchema, input, limits, async (parsed) => {
          const context = agentMutationContext(execution.toolCallId);
          const { datasetId, rowId, ...body } = parsed;
          const row = await options.client.patchRow(
            datasetId,
            rowId,
            body as PatchRowRequest,
            context,
          );
          return mutationResult(context, row);
        }),
    }),
    deleteProcessRow: tool({
      description:
        'Delete one Process row. This mutates data and always requires user approval.',
      inputSchema: deleteRowInputSchema,
      needsApproval: true,
      execute: (input, execution) =>
        executeMutation(deleteRowInputSchema, input, limits, async (parsed) => {
          const context = agentMutationContext(execution.toolCallId);
          const result = await options.client.deleteRow(
            parsed.datasetId,
            parsed.rowId,
            context,
          );
          return mutationResult(context, result);
        }),
    }),
  };
}

async function executeBounded<TSchema extends z.ZodType, TResult>(
  schema: TSchema,
  input: unknown,
  limits: ToolLimits,
  execute: (parsed: z.infer<TSchema>) => Promise<TResult>,
): Promise<TResult> {
  try {
    assertByteLimit(input, limits.maxInputBytes, 'VALIDATION_ERROR', 400);
    const parsed = schema.parse(input);
    const result = await execute(parsed);
    assertByteLimit(result, limits.maxResultBytes, 'RESPONSE_TOO_LARGE', 413);
    return result;
  } catch (error) {
    throw toProcessTableToolError(error);
  }
}

async function executeMutation<TSchema extends z.ZodType, TResult>(
  schema: TSchema,
  input: unknown,
  limits: ToolLimits,
  execute: (parsed: z.infer<TSchema>) => Promise<TResult>,
): Promise<TResult> {
  try {
    assertByteLimit(input, limits.maxInputBytes, 'VALIDATION_ERROR', 400);
    return await execute(schema.parse(input));
  } catch (error) {
    throw toProcessTableToolError(error);
  }
}

function assertByteLimit(
  value: unknown,
  maxBytes: number,
  code: string,
  statusCode: number,
): void {
  let json: string;
  try {
    json = JSON.stringify(value);
  } catch {
    throw new ProcessTableToolError({
      code: 'INVALID_RESPONSE',
      statusCode: 502,
      requestId: '',
    });
  }
  if (new TextEncoder().encode(json).byteLength > maxBytes) {
    throw new ProcessTableToolError({ code, statusCode, requestId: '' });
  }
}

function projectDiscovery(
  response: DatasetDiscoveryResponse,
): DatasetDiscoveryResponse {
  return {
    v: 1,
    datasets: response.datasets.map((dataset) => ({
      datasetId: dataset.datasetId,
      name: dataset.name,
      project: {
        id: dataset.project.id,
        name: dataset.project.name,
      },
      storageMode: dataset.storageMode,
      sourceType: dataset.sourceType,
      schemaVersion: dataset.schemaVersion,
      updatedAt: dataset.updatedAt,
      capabilities: {
        read: dataset.capabilities.read,
        write: dataset.capabilities.write,
        sync: dataset.capabilities.sync,
      },
    })),
  };
}

function projectInspection(
  dataset: DatasetResponse,
  layout: LayoutResponse,
): Record<string, unknown> {
  return {
    dataset: {
      datasetId: dataset.datasetId,
      storageMode: dataset.storageMode,
      capabilities: dataset.capabilities,
      binding: {
        datasetId: dataset.binding.datasetId,
        storageMode: dataset.binding.storageMode,
        sourceType: dataset.binding.sourceType,
        schemaVersion: dataset.binding.schemaVersion,
        syncPolicy: dataset.binding.syncPolicy,
      },
      sync: dataset.sync,
    },
    schema: {
      schemaVersion: layout.schemaVersion,
      columns: layout.columns,
      subitemColumns: layout.subitemColumns,
      structureGroups: layout.structureGroups,
      primaryGroupingColumnId: layout.primaryGroupingColumnId,
      views: layout.views,
      capabilities: layout.capabilities,
    },
  };
}

function projectQuery(
  response: QueryRowsResponse,
  maxRows: number,
): QueryRowsResponse {
  return {
    ...response,
    rows: response.rows.slice(0, maxRows),
  };
}

function agentMutationContext(toolCallId: string): TableRowMutationContext {
  const normalized = toolCallId?.trim();
  if (!normalized || normalized.length > 190) {
    throw new ProcessTableToolError({
      code: 'VALIDATION_ERROR',
      statusCode: 400,
      requestId: '',
    });
  }
  return {
    origin: 'agent',
    commandId: `ai:${normalized}`,
  };
}

function mutationResult(
  context: TableRowMutationContext,
  result: CanonicalRow | DeleteRowResponse,
): Record<string, unknown> {
  if ('deleted' in result) {
    return {
      origin: context.origin,
      commandId: context.commandId,
      rowId: result.rowId,
      deleted: result.deleted,
    };
  }
  return {
    origin: context.origin,
    commandId: context.commandId,
    rowId: result.rowId,
    datasetId: result.datasetId,
    updatedAt: result.updatedAt,
  };
}

function resolveLimits(input: ProcessTableToolsOptions['limits']): ToolLimits {
  return {
    maxQueryRows: boundedInteger(
      input?.maxQueryRows ?? PROCESS_TABLE_TOOL_LIMITS.defaultMaxQueryRows,
      PROCESS_TABLE_TOOL_LIMITS.hardMaxQueryRows,
      'maxQueryRows',
    ),
    maxInputBytes: boundedInteger(
      input?.maxInputBytes ?? PROCESS_TABLE_TOOL_LIMITS.defaultMaxInputBytes,
      PROCESS_TABLE_TOOL_LIMITS.hardMaxInputBytes,
      'maxInputBytes',
    ),
    maxResultBytes: boundedInteger(
      input?.maxResultBytes ?? PROCESS_TABLE_TOOL_LIMITS.defaultMaxResultBytes,
      PROCESS_TABLE_TOOL_LIMITS.hardMaxResultBytes,
      'maxResultBytes',
    ),
  };
}

function boundedInteger(value: number, maximum: number, name: string): number {
  if (!Number.isInteger(value) || value <= 0 || value > maximum) {
    throw new TypeError(`${name} must be an integer between 1 and ${maximum}`);
  }
  return value;
}
